class Solution {
  public long minMoves(int[] balance) {
    int n = balance.length, neg = -1;
    for (int i = 0; i < n; i++) if (balance[i] < 0) neg = i;
    if (neg < 0) return 0;
    long need = -(long) balance[neg], moves = 0;
    for (int t = 1; t <= n / 2 && need > 0; t++) {
      int a = (neg + t) % n, b = (neg - t + n) % n;
      long take = Math.min(need, Math.max(0, balance[a]));
      moves += take * t;
      need -= take;
      if (b != a && need > 0) {
        take = Math.min(need, Math.max(0, balance[b]));
        moves += take * t;
        need -= take;
      }
    }
    return need > 0 ? -1 : moves;
  }
}
